<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\IkontrolInstance; use App\Services\{CpanelService,IkontrolInstanceConnectionService,InstanceFilesystemService}; use Throwable;
class ConfigurationController extends Controller { public function index(){return view('admin.configuration.index');} public function test(string $target,CpanelService $c,InstanceFilesystemService $f,IkontrolInstanceConnectionService $db){try{$ok=match($target){'cpanel'=>(bool)$c->testConnection(),'filesystem'=>$f->rootWritable(),'mysql'=>($i=IkontrolInstance::first())?$db->test($i)['success']:false};return back()->with($ok?'success':'error',$ok?'Prueba completada correctamente.':'La prueba no fue satisfactoria.');}catch(Throwable){return back()->with('error','No fue posible completar la prueba. Revise la configuración.');}} }
